set session_replication_role = default;

--
-- La comprobación va acá y no antes: con la sesión en `replica` las llaves
-- foráneas están dormidas, así que un perfil sin cuenta entraría sin ruido.
-- Avisa y no se planta, porque una base de producción bien puede tener
-- perfiles que esta siembra no conoce. Lo que no puede volver a pasar es que
-- se rompa en silencio.
--
do $marca$
declare
  huerfanos integer;
begin
  select count(*) into huerfanos
    from public.profiles p
   where not exists (select 1 from auth.users u where u.id = p.id);

  if huerfanos > 0 then
    raise notice
      'Quedan % perfil(es) sin cuenta en auth.users. Un perfil huérfano no puede '
      'iniciar sesión y sus políticas nunca dan verdadero.', huerfanos;
  end if;
end
$marca$;

notify pgrst, 'reload schema';
