INSERT INTO public.cursos VALUES ('3c8b177c-5a9d-4db7-812f-db8192b5f91c', NULL, 'introduccion', 8, 'basico', 'online', true, true, 1, '2026-09-08 05:24:11.184472+00', '{"en": "Introduction to caring for an older person", "es-AR": "Introducción al cuidado de la persona mayor", "pt-BR": "Introdução ao cuidado da pessoa idosa"}', '{"en": "Core concepts of ageing, basic needs and how to accompany the person being cared for day by day.", "es-AR": "Conceptos fundamentales del envejecimiento, necesidades básicas y cómo acompañar a la persona cuidada en el día a día.", "pt-BR": "Conceitos fundamentais do envelhecimento, necessidades básicas e como acompanhar a pessoa cuidada no dia a dia."}', '{"en": "Basic level", "es-AR": "Nivel básico", "pt-BR": "Nível básico"}', 'assets/images/monitoreo_cuidado.png');
INSERT INTO public.cursos VALUES ('67363f36-c4b6-4248-b6df-42bc07efe150', NULL, 'demencias', 12, 'intermedio', 'online', true, true, 2, '2026-09-08 05:24:11.184472+00', '{"en": "Alzheimer''s and other dementias: what to expect and how to act", "es-AR": "Alzheimer y otras demencias: qué esperar y cómo actuar", "pt-BR": "Alzheimer e outras demências: o que esperar e como agir"}', '{"en": "A practical guide to understanding cognitive impairment, handling difficult situations and sustaining the quality of life of the person being cared for.", "es-AR": "Guía práctica para entender el deterioro cognitivo, manejar situaciones difíciles y sostener la calidad de vida de la persona cuidada.", "pt-BR": "Guia prático para entender o declínio cognitivo, lidar com situações difíceis e sustentar a qualidade de vida da pessoa cuidada."}', '{"en": "Intermediate", "es-AR": "Intermedio", "pt-BR": "Intermediário"}', 'assets/images/acompanamiento_online.png');
INSERT INTO public.cursos VALUES ('8b321a83-5c30-4a9e-ae17-88101d26bd98', NULL, 'bienestar_cuidador', 6, 'basico', 'online', true, true, 3, '2026-09-08 05:24:11.184472+00', '{"en": "The wellbeing of whoever cares", "es-AR": "El bienestar de quien cuida", "pt-BR": "O bem-estar de quem cuida"}', '{"en": "Tools to prevent caregiver burnout syndrome, manage stress and sustain one''s own emotional health.", "es-AR": "Herramientas para prevenir el síndrome del cuidador, manejar el estrés y sostener la propia salud emocional.", "pt-BR": "Ferramentas para prevenir a síndrome do cuidador, lidar com o estresse e sustentar a própria saúde emocional."}', '{"en": "Wellbeing", "es-AR": "Bienestar", "pt-BR": "Bem-estar"}', 'assets/images/vida_activa.png');
INSERT INTO public.cursos VALUES ('0f574413-e778-46a2-8a56-7e6fa8bc16bb', NULL, 'medicamentos', 5, 'intermedio', 'online', true, true, 4, '2026-09-08 05:24:11.184472+00', '{"en": "Administration of medicines and health monitoring at home", "es-AR": "Administración de medicamentos y control de salud en el hogar", "pt-BR": "Administração de medicamentos e controle de saúde em casa"}', '{"en": "Organising medication, recognising warning signs and coordinating with the medical team.", "es-AR": "Organizar la medicación, reconocer señales de alerta y coordinar con el equipo médico.", "pt-BR": "Organizar a medicação, reconhecer sinais de alerta e coordenar com a equipe médica."}', '{"en": "Health", "es-AR": "Salud", "pt-BR": "Saúde"}', 'assets/images/gestor_medicamentos.png');
INSERT INTO public.cursos VALUES ('f9ed3099-d7ac-48d0-a639-82fc4d9c6b62', NULL, 'comunicacion', 4, 'basico', 'online', true, true, 5, '2026-09-08 05:24:11.184472+00', '{"en": "Empathetic communication with the person being cared for", "es-AR": "Comunicación empática con la persona cuidada", "pt-BR": "Comunicação empática com a pessoa cuidada"}', '{"en": "Communication techniques adapted to ageing, how to give bad news and how to handle the conflicts that surround care.", "es-AR": "Técnicas de comunicación adaptadas al envejecimiento, cómo dar malas noticias y cómo manejar los conflictos que rodean al cuidado.", "pt-BR": "Técnicas de comunicação adaptadas ao envelhecimento, como dar más notícias e como lidar com os conflitos que cercam o cuidado."}', '{"en": "Communication", "es-AR": "Comunicación", "pt-BR": "Comunicação"}', 'assets/images/asistente_telefono.png');
INSERT INTO public.cursos VALUES ('7ca84e50-3df7-498a-9fda-ed0d2373aed6', NULL, 'cuidados_avanzados', 16, 'avanzado', 'online', true, true, 6, '2026-09-08 05:24:11.184472+00', '{"en": "Advanced care: bedbound patients and palliative care", "es-AR": "Cuidados avanzados: pacientes postrados y cuidados paliativos", "pt-BR": "Cuidados avançados: pacientes acamados e cuidados paliativos"}', '{"en": "Moving and handling, prevention of pressure sores, end-of-life care and emotional companionship.", "es-AR": "Movilización, prevención de escaras, cuidados al final de la vida y acompañamiento emocional.", "pt-BR": "Mobilização, prevenção de escaras, cuidados no fim da vida e acompanhamento emocional."}', '{"en": "Advanced", "es-AR": "Avanzado", "pt-BR": "Avançado"}', 'assets/images/hero_cuidadores.png');
