INSERT INTO public.vocabulario_items VALUES ('4bb9ec24-fd6d-4a3f-af67-373db855482d', NULL, 'bf76c29e-d7f3-492e-9bb6-bee860d5b85c', 'titulo', '{"en": "Qualification backing the profession", "es-AR": "Título que respalda la profesión", "pt-BR": "Diploma que respalda a profissão"}', false, NULL, '{"puerta": "publicacion", "condicional_a": "tipo_asistente.requiere_matricula"}', 3, true, '2026-09-08 05:24:11.469064+00');
