INSERT INTO public.patrones_de_contacto VALUES ('0acc5716-7bb1-4cfe-9634-b65ee24dd3f4', 'telefono', '(?:\d[ .()\-]{0,2}){7,}', 'g', '{"en": "This looks like a phone number.", "es-AR": "Parece un número de teléfono.", "pt-BR": "Parece um número de telefone."}', 1, true, '2026-09-08 05:24:11.701399+00');
INSERT INTO public.patrones_de_contacto VALUES ('e0529ed1-960f-4a26-b51a-af4e750bcd5a', 'telefono_en_letras', '(?:\b(?:cero|uno|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve)\b[ ,.\-]*){7,}', 'gi', '{"en": "This looks like a phone number spelled out in words.", "es-AR": "Parece un número de teléfono escrito con palabras.", "pt-BR": "Parece um número de telefone escrito por extenso."}', 2, true, '2026-09-08 05:24:11.701399+00');
INSERT INTO public.patrones_de_contacto VALUES ('72964415-c1c6-4b4f-b140-c50737c406ab', 'correo', '[A-Za-z0-9._%+-]+ ?(?:@|\( ?at ?\)|\[ ?at ?\]|\barroba\b) ?[A-Za-z0-9-]+ ?(?:\.|\bpunto\b|\bponto\b) ?[A-Za-z]{2,}', 'gi', '{"en": "This looks like an email address.", "es-AR": "Parece una dirección de correo.", "pt-BR": "Parece um endereço de e-mail."}', 3, true, '2026-09-08 05:24:11.701399+00');
INSERT INTO public.patrones_de_contacto VALUES ('6df14938-575e-4b90-a721-179b75564f1f', 'domicilio', '\b(?:calle|avenida|av|avda|pasaje|psje|diagonal)\b\.? ?[A-Za-zÀ-ÿ'' ]{0,24}?\d{1,5}\b', 'gi', '{"en": "This looks like a street address.", "es-AR": "Parece un domicilio.", "pt-BR": "Parece um endereço residencial."}', 4, true, '2026-09-08 05:24:11.701399+00');
INSERT INTO public.patrones_de_contacto VALUES ('a2760c59-b4cf-4b05-a1de-b1b1644095cd', 'domicilio_por_partes', '\b(?:piso|depto|dpto|departamento|timbre|altura)\b\.? ?\d{1,5}\b', 'gi', '{"en": "This looks like part of a street address.", "es-AR": "Parece parte de un domicilio.", "pt-BR": "Parece parte de um endereço residencial."}', 5, true, '2026-09-08 05:24:11.701399+00');
